SELECT *
FROM product
WHERE shorten_code = #{shortenCode}
  AND base_date = (
    SELECT MAX(base_date)
    FROM product
    WHERE shorten_code = #{shortenCode}
)

SELECT CAST(shorten_code AS UNSIGNED) as productId
FROM product
WHERE item_name = #{itemName}
  AND base_date = (
    SELECT MAX(base_date)
    FROM product
    WHERE item_name = #{itemName}
)
LIMIT 1
